/**
 * `virtual:pwa-register`, for the test runner.
 *
 * The real module is generated by `vite-plugin-pwa` at build time and does not
 * exist on disk, so esbuild cannot resolve it — and `lib/updates.ts` imports it
 * at the top level, which would take out any test file that reaches that module
 * through an import chain.
 *
 * A stub rather than marking it external: external would defer the failure to
 * Node, which cannot resolve it either. What the tests exercise is the decision
 * about *when* to take a waiting version, and none of that needs a service
 * worker — `__setWaitingForTest` supplies the activation directly. So this
 * returns a registration that never reports an update, which is also the honest
 * answer for a run with no service worker in it.
 */
export function registerSW() {
  return async () => {}
}
